import sys
IS_LOCAL = False

def readMultiple(f):
	return f(map(int, input().split()))

def check_seq(n, a):
	d = a[1][0] - a[0][0]
	(found, ind, prev) = (False, a[0][1], a[1][0])
	for i in range(2, n):
		if abs(a[i][0] - prev - d) > 0.1:
			if found:
				return (False, -1)
			found = True
			ind = a[i][1]
			continue
		prev = a[i][0]
	return (True, ind)

def main():
	n = 5
	a = [2, 6, 8, 7, 4]
	if not IS_LOCAL:
		n = int(input())
		a = readMultiple(list)
	if n <= 3:
		print(1)
		return
	a = [(x, i + 1) for (i, x) in enumerate(a)]
	a = sorted(a)
	(is_good, ind) = check_seq(n, a)
	if not is_good:
		(is_good, ind) = check_seq(n, list(reversed(a)))
	print(ind)
if len(sys.argv) > 1 and sys.argv[1] == 'True':
	IS_LOCAL = True
main()
